import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { CodemodAdapterId } from "../packages/codemod/src/swap/index.ts";
import { adapterContractFixtures } from "../packages/codemod/proof/adapter-contract-fixtures.ts";

const routeDirectory = resolve(import.meta.dirname, "../packages/codemod/tests/routes");
const roundTripDirectory = resolve(import.meta.dirname, "../packages/codemod/tests/roundtrips");
const generatedHeader =
	"// Generated by scripts/generate-adapter-route-specs.ts. Do not edit by hand.";
const enumMembers = new Map(
	Object.entries(CodemodAdapterId).map(([name, id]) => [id, name] as const),
);

function identifier(id: CodemodAdapterId): string {
	const member = enumMembers.get(id);
	if (member === undefined) throw new Error(`missing CodemodAdapterId member for ${id}`);
	return `CodemodAdapterId.${member}`;
}

function fileName(source: CodemodAdapterId, target: CodemodAdapterId): string {
	return `${source}-to-${target}.test.ts`;
}

function roundTripFileName(source: CodemodAdapterId, target: CodemodAdapterId): string {
	return `${source}-to-${target}-to-${source}.test.ts`;
}

function semanticFor(adapter: CodemodAdapterId): string {
	if (adapter === CodemodAdapterId.StyledComponents)
		return "{ source: { framework: BuiltinHostFramework.React } }";
	if (adapter === CodemodAdapterId.SolidStyled)
		return "{ source: { framework: BuiltinHostFramework.Solid } }";
	if (adapter === CodemodAdapterId.VueStyled)
		return "{ source: { framework: BuiltinHostFramework.Vue } }";
	if (
		adapter === CodemodAdapterId.ChakraUi ||
		adapter === CodemodAdapterId.Mui ||
		adapter === CodemodAdapterId.Mantine
	)
		return "{ source: { framework: BuiltinHostFramework.React } }";
	return "undefined";
}

function edgeSource(adapter: CodemodAdapterId, source: string): string {
	if (adapter === CodemodAdapterId.Mantine && source.includes("c='red'"))
		return source.replace("c='red'", "c={theme.foreground}");
	if (source.includes("'red'")) return source.replaceAll("'red'", "theme.foreground");
	if (source.includes('"red"')) return source.replaceAll('"red"', "theme.foreground");
	if (source.includes("color: red"))
		return source.replaceAll("color: red", "color: ${theme.foreground}");
	if (source.includes("bg='tomato'")) return source.replace("bg='tomato'", "bg={theme.foreground}");
	if (adapter === CodemodAdapterId.UnoCSS)
		return '<div className="flex unknown-project-utility" />';
	return `${source}\nconst unresolvedStyle = runtimeTheme.foreground;`;
}

